// Client clarification drafts. Built from templates, not generated by an LLM:
// the Squad Lead reviews and posts them, so they must be predictable.

import { PASS, type Audience, type Verdict } from "./models.ts";

export function humanJoin(items: string[]): string {
  return items.length === 1 ? items[0] : `${items.slice(0, -1).join(", ")} and ${items.at(-1)}`;
}

function bannedAsk(phrases: string[]): string {
  const quoted = humanJoin(phrases.map((p) => `"${p}"`));
  const which = phrases.length === 1 ? "is on the list of claims" : "are on the list of claims";
  return `The copy includes ${quoted}, which ${which} we've agreed not to use. Could you share an alternative line?`;
}

function asks(v: Verdict, audience: Audience): string[] {
  const banned = v.reasons.filter((r) => r.code === "banned_claim" && r.evidence).map((r) => r.evidence!);
  const out: string[] = [];
  for (const r of v.reasons) {
    if (r.audience !== audience || !r.client_ask) continue;
    let ask: string;
    if (r.code === "banned_claim") {
      // All banned phrases go into one ask, placed where the first one was.
      ask = bannedAsk(banned);
    } else if (r.code === "brain_rule" && banned.some((b) => (r.evidence ?? "").toLowerCase().includes(b.toLowerCase()))) {
      // A Brain-rule hit on the same words as a banned phrase is one
      // problem for the client, so ask about it once.
      continue;
    } else {
      ask = r.client_ask;
    }
    if (!out.includes(ask)) out.push(ask);
  }
  return out;
}

export function compose(title: string, items: string[]): string {
  const body =
    items.length === 1
      ? `one quick check: ${items[0][0].toLowerCase()}${items[0].slice(1)}`
      : `a few quick checks:\n${items.map((a) => `• ${a}`).join("\n")}`;
  return `Hi team, before we start on "${title}", ${body}\nAs soon as we hear back, it goes straight into production.`;
}

export function attach(v: Verdict): void {
  if (v.status === PASS) return;
  const clientAsks = asks(v, "client");
  const approvalAsks = asks(v, "approval");
  if (clientAsks.length) {
    // We are messaging the client anyway: ask everything in one message.
    v.client_message = compose(v.title, [...clientAsks, ...approvalAsks]);
  } else if (approvalAsks.length) {
    // The Squad Lead can unblock this alone; only if they decline does
    // the client hear about it.
    v.client_message_if_declined = compose(v.title, approvalAsks);
  }
}
